// THE RIDE BUTTONS (the user's own pictures, 2026-11-24): the camera switch and 'get off', two round neon buttons drawn over the left controls while riding (192 x 192 each)
const RIDE_BTN_ART = { cam: 'data:image/webp;base64,', off: 'data:image/webp;base64,' };
if (typeof Image !== 'undefined') for (const k of ['cam', 'off']) { const i = new Image(); i.src = RIDE_BTN_ART[k]; RIDE_BTN_ART[k + 'Img'] = i; }
